use retail_sales;
-- Q1 Total Revenue Generated by each product
select p.product_id,p.product_name, price as unit_price,
	sum(p.price*i.quantity) as Total_revenue
from product p join order_items i  
on p.product_id=i.product_id
group by p.product_id,p.product_name;

-- Q2 Total number of products available,average product price,highest-priced product with its name for each category.
select category_name, 
	 count(distinct p.product_id) as No_of_Products,
     avg(p.price) as Average_Product_price,
     group_concat(
		case
			when p.price=(
				select max(pp.price)
				from product pp
                where pp.category_id = p.category_id)
			then p.product_name 
		end
     ) as Highest_priced_product,
     max(p.price) as Highest_price
from product p join category c
on c.category_id=p.category_id 
group by c.category_name;

-- Q3  Top-selling products based on total quantity sold.
select p.product_id,p.product_name,
	sum(i.quantity) as Total_Sold_Quantity
from product p join order_items i
on p.product_id=i.product_id
group by p.product_id
order by sum(i.quantity) desc
limit 10;

-- Q4 Products that have never been ordered.
select p.product_id,p.product_name
from product p 
left join order_items i
on p.product_id=i.product_id
where i.product_id is null;

-- Q5 locations having the highest number of customers.
select l.city,
	sum(distinct c.customer_id) as No_of_customers
from customer c 
join location l
on c.location_id=l.location_id
group by l.city
order by No_of_customers desc;

-- Q6 Number of times customer ordered
select c.customer_id,c.customer_name,
	count(distinct order_id) as Times_ordered
from customer c left join orders o
on c.customer_id=o.customer_id
group by c.customer_id
order by Times_ordered desc;

-- Q7 Customer who placed order and their total purchase value
select c.customer_id,c.customer_name,
	sum(p.price*i.quantity) as Total_Purchase_Value
from product p left join order_items i  
on p.product_id=i.product_id
left join orders o 
on o.order_id=i.order_id
left join customer c
on c.customer_id=o.customer_id
group by c.customer_id
order by c.customer_id;

-- Q8 customer who purchased products from the highest number of different categories.
select c.customer_id,c.customer_name,
	count(distinct cg.category_id) as No_of_distinct_Category
from customer c join orders o
on o.customer_id=c.customer_id
join order_items i
on o.order_id=i.order_id
join product p
on p.product_id=i.product_id
join category cg
on p.category_id=cg.category_id
group by c.customer_id
order by No_of_distinct_category desc;

-- Q9 Month wise orders placed and revenue generated
select monthname(o.order_date),
	count(distinct o.order_id) as Total_orders,
    sum(p.price*(p.gst_rate/100)*i.quantity + o.packaging_cost) as Revenue_Generated
from product p join order_items i 
on p.product_id=i.product_id
join orders o
on o.order_id=i.order_id
group by monthname(o.order_date);

-- 10 orders generated by each category
select c.category_id,c.category_name,
	count(distinct i.order_id) as Order_numbers
from category c join product p
on c.category_id=p.category_id
join order_items i
on i.product_id=p.product_id
group by c.category_id,c.category_name;

-- Q11 total inventory value available in each warehouse. 
select w.warehouse_id, sum(p.price*i.quantity)
from warehouse w join inventory i 
on w.warehouse_id=i.warehouse_id
join product p 
on p.product_id=i.product_id
group by w.warehouse_id;

-- Q12 product having the highest inventory quantity in each warehouse.
select w.warehouse_id,p.product_name,
	i.quantity as Highest_Quantity
from warehouse w join inventory i 
on w.warehouse_id=i.warehouse_id
join product p 
on p.product_id=i.product_id
where i.quantity = (
    select MAX(i2.quantity)
    from inventory i2
    where i2.warehouse_id = i.warehouse_id
);

-- Q13 total inventory value available in each store. 
select s.store_id, sum(p.price*i.quantity) as total_inventory
from store s join store_inventory i 
on s.store_id=i.store_id
join product p 
on p.product_id=i.product_id
group by s.store_id;

-- Q14 product having the highest inventory quantity in each store.
select s.store_id,p.product_name,
	i.quantity as Highest_Quantity
from store s join store_inventory i 
on s.store_id=i.store_id
join product p 
on p.product_id=i.product_id
where i.quantity = (
    select MAX(i2.quantity)
    from store_inventory i2
    where i2.store_id = i.store_id
);

-- Q15 Compare the total warehouse inventory quantity and store inventory quantity for each product.
select p.product_id,p.product_name,
	 coalesce(wi.warehouse_inventory,0)as warehouse_inventory,
     coalesce(si.store_inventory,0) as store_inventory
from product p 
left join ( select product_id,sum(quantity) as warehouse_inventory
			from inventory
            group by product_id) wi
on wi.product_id=p.product_id
left join  ( select product_id,sum(quantity) as store_inventory
			from store_inventory
            group by product_id) si
on si.product_id=p.product_id;


-- Q16 dealer supplying max number of products
select d.dealer_id,
		count(d.product_id) as max_product_no
from dealer_product d
group by d.dealer_id 
order by max_product_no desc;
