-- Q17 dealer offering the lowest purchase price for each product.
select p.product_id,p.product_name,d.dealer_name,
	dp.purchase_price as Lowest_purchase_price,
    l.city
from product p left join dealer_product dp
on p.product_id= dp.product_id
join dealer d
on d.dealer_id=dp.dealer_id
join location l
on d.location_id=l.location_id
where dp.purchase_price=(select min(dp2.purchase_price)
						 from dealer_product dp2
                         where dp.product_id=dp2.product_id)
order by p.product_id;


-- Q18 total quantity supplied by each dealer. (using existing view)
select dealer_id,
		sum(quantity) as total_supply_quantity
from dealer_supply_history
group by dealer_id
order by total_supply_quantity;

-- Q19 total sales of each dealer(using existing view)
select dealer_id,
		sum(line_total) as total_supply_sales
from dealer_supply_history 
group by dealer_id
order by total_supply_sales;

-- Q20 dealer(s) supplying products belonging to the maximum number of different categories.
select dp.dealer_id,count( distinct c.category_id) Max_Categories
from dealer_product dp join product p
on dp.product_id=p.product_id
join category c
on c.category_id=p.category_id
group by dp.dealer_id
-- having count( distinct c.category_id)=( select max(category_num)
--                                         from(   select count(distinct category_id)as category_num
--                                                 from dealer_product join product
--                                                 on dealer_product.product_id=product.product_id
--                                                 group by dealer_id) as temp
-- 										)
order by  Max_Categories desc;

-- Q21 total quantity tranported from dealer and shiped till now for each product
select p.product_id,p.product_name,
	 coalesce(t.transport_quantity,0) as transport_quantity,
     coalesce(o.sold_quantity,0) as sold_quantity
from product p 
left join ( select ti.product_id,sum(ti.quantity) as transport_quantity
			from transport_item ti join transport t
            on ti.transport_id=t.transport_id
            where t.source_type='Dealer'
            group by ti.product_id) t
on t.product_id=p.product_id
left join ( select oi.product_id,sum(oi.quantity) as sold_quantity
			from order_items oi join orders o
            on o.order_id=oi.order_id
			group by oi.product_id) o
on o.product_id=p.product_id;

-- Q22 total transportation cost for each transport company and total transport batch
select transport_company,
	sum(cost) as Transport_cost,
    count(distinct transport_id) as total_transports
from transport
group by transport_company;

-- Q23 total shipping cost for each delivery company and total shippments
select d.company_id,d.company_name,
	sum(s.shippment_cost) as Shippment_cost,
    count(distinct shippment_id) as total_shipments
from delivery_company d join shippment s
on d.company_id=s.company_id
group by d.company_id,d.company_name 
order by Shippment_cost desc;

-- Q24 average transportation duration for each transport type.
select transport_type,round(avg(datediff(arrival_date,dispatch_date)),2) as avg_transportation_duration
from transport
group by transport_type;

-- Q25 average shipping duration
select round(avg(datediff(delivery_date,shippment_date)),2) as avg_shipping_duration
from shippment;

-- Q26 average delivery duration
select round(avg(datediff(s.delivery_date,o.order_date)),2) as avg_delivery_duration
from shippment s join orders o
on o.order_id=s.order_id;

-- Q27 source-destination combinations handling the highest quantity of goods.
select t.transport_id,source_type,source_id,destination_type,destination_id,
		sum(ti.quantity) as Total_quantity
from transport t join transport_item ti 
on t.transport_id=ti.transport_id
group by t.transport_id
order by Total_quantity desc;

-- Q28 shipments carried the highest quantity
select s.shippment_id,source_warehouse_id,source_store_id,l.city,
		sum(oi.quantity) as total_quantity
from shippment s join order_items oi
on s.order_id=oi.order_id
join location l
on l.location_id=s.destination_location_id
group by s.shippment_id
order by total_quantity desc;

-- Q29 destination locations receiving the highest number of shipments.
select l.location_id,l.city,
	count(s.shippment_id) as Total_shippment
from location l
left join shippment s
on l.location_id=s.destination_location_id
group by l.location_id,l.city
order by Total_shippment desc;

-- Q30 Identify products having high sales quantity but low current inventory.

-- Q31 Identify products having high inventory but comparatively low sales.

-- Q32 Compare product selling price with dealer purchase price to determine the potential gross margin for each product.
select p.product_id,p.product_name,p.price as selling_price,dp.dealer_id,dp.purchase_price,
		ROUND(p.price - dp.purchase_price, 2) as gross_margin,
		ROUND(((p.price - dp.purchase_price) / dp.purchase_price) * 100,2) as gross_margin_percent
from product p
join dealer_product dp
on p.product_id = dp.product_id
order by gross_margin_percent desc;

